-- ==================================================================
-- 최초 스키마. JPA 엔티티에서 Hibernate 가 OracleDialect 로 생성한 DDL 이다.
-- (생성 방법: jakarta.persistence.schema-generation.scripts.action=create)
--
-- ⚠️ 한 번이라도 적용된 뒤에는 이 파일을 고치지 말 것.
--   Flyway 는 적용 시점의 체크섬을 flyway_schema_history 에 기록한다. 내용이
--   바뀌면 다음 기동에서 validate 가 실패해 앱이 아예 뜨지 않는다.
--   스키마를 바꿔야 하면 V2, V3 를 새로 추가한다.
--
-- 로컬/CI 는 H2 라 Flyway 를 끄고 ddl-auto 로 만든다(application.yml).
-- 이 파일은 운영 Oracle 에서만 실행된다.
-- ==================================================================

create table admin_comment_report (report_count number(10,0) not null, comment_id number(19,0) not null unique, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), primary key (id));
create table admin_community_member_ban (banned_until timestamp(9), created_at timestamp(9), id number(19,0) generated by default as identity, member_id number(19,0) not null unique, updated_at timestamp(9), reason varchar2(255 char) not null, primary key (id));
create table admin_post_report (report_count number(10,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, post_id number(19,0) not null unique, updated_at timestamp(9), primary key (id));
create table app_usage (child_id number(19,0) not null, created_at timestamp(9), duration_sec number(19,0) not null, id number(19,0) generated by default as identity, recorded_at timestamp(9) not null, updated_at timestamp(9), app_name varchar2(255 char) not null, primary key (id));
create table block_rule (child_id number(19,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), pattern varchar2(255 char) not null, primary key (id));
create table board (answered number(1,0) not null check ((answered in (0,1))), created_at timestamp(9), id number(19,0) generated by default as identity, member_id number(19,0) not null, updated_at timestamp(9), attachment_url varchar2(255 char), content CLOB not null, link_url varchar2(255 char), title varchar2(255 char) not null, primary key (id));
create table charge_order (amount number(19,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, owner_id number(19,0) not null, updated_at timestamp(9), merchant_uid varchar2(255 char) not null unique, pg_transaction_id varchar2(255 char), status varchar2(255 char) not null check ((status in ('READY','PAID','CANCELLED'))), primary key (id));
create table community_post (created_at timestamp(9), id number(19,0) generated by default as identity, member_id number(19,0) not null, updated_at timestamp(9), content CLOB not null, title varchar2(255 char) not null, primary key (id));
create table community_post_attachment (post_id number(19,0) not null, url varchar2(255 char));
create table community_post_comment (created_at timestamp(9), id number(19,0) generated by default as identity, member_id number(19,0) not null, post_id number(19,0) not null, updated_at timestamp(9), content CLOB not null, primary key (id));
create table community_post_like (created_at timestamp(9), id number(19,0) generated by default as identity, member_id number(19,0) not null, post_id number(19,0) not null, updated_at timestamp(9), primary key (id), unique (post_id, member_id));
create table community_post_link (post_id number(19,0) not null, url varchar2(255 char));
create table device_event (child_id number(19,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), device_id varchar2(255 char) not null, type varchar2(255 char) not null check ((type in ('POWER_OFF','GPS_OFF'))), primary key (id));
create table device_token (created_at timestamp(9), id number(19,0) generated by default as identity, member_id number(19,0) not null unique, updated_at timestamp(9), token varchar2(500 char) not null, primary key (id));
create table email_verification (used number(1,0) not null check ((used in (0,1))), created_at timestamp(9), expires_at timestamp(9) not null, id number(19,0) generated by default as identity, target_member_id number(19,0) not null, updated_at timestamp(9), code varchar2(255 char) not null, email varchar2(255 char) not null, purpose varchar2(255 char) not null check ((purpose in ('FIND_ID','RESET_PASSWORD'))), primary key (id));
create table harmful_keyword (created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), keyword varchar2(255 char) not null unique, primary key (id));
create table inquiry_answer (board_id number(19,0) not null unique, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), content CLOB not null, primary key (id));
create table member (birth_date date not null, is_deleted number(1,0) not null check ((is_deleted in (0,1))), created_at timestamp(9), id number(19,0) generated by default as identity, parent_id number(19,0), updated_at timestamp(9), address varchar2(255 char), email varchar2(255 char) unique, login_id varchar2(255 char) not null unique, nickname varchar2(255 char), password varchar2(255 char) not null, phone_number varchar2(255 char) not null, profile_image_url varchar2(255 char), role varchar2(255 char) not null check ((role in ('SUPER_ADMIN','GENERAL_ADMIN','COMMUNITY_ADMIN','INQUIRY_ADMIN','PARENT','CHILD'))), username varchar2(255 char) not null, primary key (id));
create table notice (author_id number(19,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), attachment_url varchar2(255 char), link_url varchar2(255 char), title varchar2(255 char) not null, content clob not null, primary key (id));
create table notification (is_read number(1,0) not null check ((is_read in (0,1))), created_at timestamp(9), id number(19,0) generated by default as identity, recipient_id number(19,0) not null, updated_at timestamp(9), message varchar2(255 char) not null, type varchar2(255 char) not null check ((type in ('LOCATION_ENTER','LOCATION_EXIT','LOCATION_ARRIVED','DEVICE_POWER_OFF','HARMFUL_SITE','APP_USAGE','NOTICE','PAYMENT_APPROVED','PAYMENT_CANCELED','SCREENSHOT_REQUESTED','ETC'))), primary key (id));
create table notification_setting (created_at timestamp(9), id number(19,0) generated by default as identity, member_id number(19,0) not null unique, updated_at timestamp(9), primary key (id));
create table notification_setting_toggle (enabled number(1,0) not null check ((enabled in (0,1))), notification_setting_id number(19,0) not null, type varchar2(255 char) not null check ((type in ('LOCATION_ENTER','LOCATION_EXIT','LOCATION_ARRIVED','DEVICE_POWER_OFF','HARMFUL_SITE','APP_USAGE','NOTICE','PAYMENT_APPROVED','PAYMENT_CANCELED','SCREENSHOT_REQUESTED','ETC'))), primary key (notification_setting_id, type));
create table pairing_code (created_at timestamp(9), expires_at timestamp(9) not null, id number(19,0) generated by default as identity, parent_id number(19,0) not null, updated_at timestamp(9), code varchar2(255 char) not null unique, primary key (id));
create table place (latitude binary_double not null, longitude binary_double not null, radius_meters binary_double not null, child_id number(19,0) not null, id number(19,0) generated by default as identity, name varchar2(255 char) not null, type varchar2(255 char) not null check ((type in ('GEOFENCE','DESTINATION'))), primary key (id));
create table place_event (child_id number(19,0) not null, id number(19,0) generated by default as identity, occurred_at timestamp(9) not null, place_id number(19,0) not null, event_type varchar2(255 char) not null check ((event_type in ('ENTER','EXIT','ARRIVED'))), primary key (id));
create table qr_payment (amount number(19,0), child_id number(19,0) not null, created_at timestamp(9), expires_at timestamp(9) not null, id number(19,0) generated by default as identity, paid_at timestamp(9), terminal_id number(19,0), updated_at timestamp(9), qr_token varchar2(255 char) not null unique, status varchar2(255 char) not null check ((status in ('ISSUED','PAID','EXPIRED','CANCELLED'))), store_name varchar2(255 char), primary key (id));
create table refresh_token (created_at timestamp(9), expires_at timestamp(9) not null, id number(19,0) generated by default as identity, member_id number(19,0) not null, updated_at timestamp(9), token_hash varchar2(255 char) not null unique, primary key (id));
create table screenshot (captured_at timestamp(9) not null, child_id number(19,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), capture_trigger varchar2(255 char) not null check ((capture_trigger in ('SCHEDULED','MANUAL'))), image_path varchar2(255 char) not null, primary key (id));
create table store_terminal (created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), status varchar2(255 char) not null check ((status in ('ACTIVE','REVOKED'))), store_name varchar2(255 char) not null, terminal_token varchar2(255 char) not null unique, primary key (id));
create table track_segment (child_id number(19,0) not null, created_at timestamp(9) not null, id number(19,0) generated by default as identity, segment_end timestamp(9) not null, segment_start timestamp(9) not null, updated_at timestamp(9) not null, latitude varchar2(255 char) not null, longitude varchar2(255 char) not null, primary key (id));
create table tracking_setting (realtime_enabled number(1,0) not null check ((realtime_enabled in (0,1))), child_id number(19,0) not null unique, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), primary key (id));
create table wallet (balance number(19,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, owner_id number(19,0) not null unique, updated_at timestamp(9), primary key (id));
create table wallet_transaction (amount number(19,0) not null, balance_after number(19,0) not null, created_at timestamp(9), id number(19,0) generated by default as identity, updated_at timestamp(9), wallet_id number(19,0) not null, ref_uid varchar2(255 char), type varchar2(255 char) not null check ((type in ('CHARGE','REFUND','TRANSFER_IN','TRANSFER_OUT','PAYMENT','PAYMENT_CANCEL','ADJUST'))), primary key (id));
create index idx_usage_child_recorded on app_usage (child_id, recorded_at);
create index idx_usage_created_at on app_usage (created_at);
create index idx_block_rule_child on block_rule (child_id);
create index idx_charge_order_merchant on charge_order (merchant_uid);
create index idx_device_event_child on device_event (child_id, created_at);
create index idx_notification_recipient on notification (recipient_id, created_at);
create index idx_place_child on place (child_id);
create index idx_event_child_place on place_event (child_id, place_id, occurred_at);
create index idx_event_place_type on place_event (place_id, event_type);
create index idx_qr_payment_token on qr_payment (qr_token);
create index idx_screenshot_child on screenshot (child_id, captured_at);
create index idx_store_terminal_token on store_terminal (terminal_token);
create index idx_track_child_window on track_segment (child_id, segment_start);
create index idx_track_created_at on track_segment (created_at);
create index idx_wallet_tx_wallet on wallet_transaction (wallet_id, id);
